n    \"dsh-mnemon-source-documents\": \"0.5.11\",\n    \"dsh-mnemon-source-memory-spaces\": \"0.5.24\",\n    \"dsh-mnemon-source-runtime\": \"0.5.16\",\n    \"dsh-mnemon-source-skills\": \"0.5.4\",\n    \"dsh-mnemon-strategy-auto-capture\": \"0.5.5\",\n    \"dsh-mnemon-strategy-default-three-tier\": \"0.5.11\",\n    \"dsh-mnemon-strategy-general\": \"0.5.1\",\n    \"dsh-mnemon-strategy-light-context\": \"0.5.6\",\n    \"dsh-mnemon-strategy-scoped\": \"0.5.5\",\n    \"fflate\": \"^0.8.3\",\n    \"yaml\": \"^2.9.0\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4\",\n    \"@deepseek-ai/dsh-app-boot\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-typert-protocol\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.1 <0.3.0-0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@arethetypeswrong/cli\": \"^0.18.5\",\n    \"@changesets/cli\": \"^2.31.1\",\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-agent-loop\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-api-gateway\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-app-boot\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \"0.