.3.1\",\n    \"simple-icons\": \"16.31.0\",\n    \"tsdown\": \"^0.22.0\",\n    \"typescript\": \"^5.9.0\",\n    \"vitest\": \"^3.2.0\",\n    \"zustand\": \"~4.4.7\"\n  },\n  \"bin\": {\n    \"dsh-mnemon-repair-session\": \"bin/repair-legacy-session.mjs\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-app-boot\": {\n      \"optional\": true\n    }\n  }\n}\n"
